// Resuelve "Arturo" a la persona concreta que puede dar ESE servicio.
//
// La clave del diseño: se pregunta primero por el POOL del servicio, así que
// cuando el nombre no encaja se puede decir quién SÍ lo lleva en vez de un "no
// puedo" que obliga al cliente a adivinar. Ese era el fallo real: Lucía anotaba
// una tarea prometiendo que Arturo atendería un alta de autónomo que Arturo no
// hace.
//
// El LLM nunca ve un UUID: entra un nombre y sale un `resource_id` que solo
// viaja entre workflows.
const inp = $('When Executed by Another Workflow').first().json;
const consulta = (inp.profesional || '').toString().trim();

const cuerpo = (r) => {
  const b = (r && (r.body ?? r)) || {};
  return Array.isArray(b.data) ? b.data : [];
};
const pool = cuerpo($('HTTP · Pool del servicio').first().json);
const plantilla = cuerpo($json);

// Sin acentos y en minúscula: "Ledesma" y "ledesma" son la misma persona, y
// nadie escribe "Benavídez" con tilde por WhatsApp.
const plano = (s) => (s || '').toString().normalize('NFD')
  .replace(/[̀-ͯ]/g, '').toLowerCase().trim();

const personas = pool.map((fila) => {
  const rec = fila.resource_id || {};
  const emp = rec.employee_id || {};
  const nombre = [emp.first_name, emp.last_name].filter(Boolean).join(' ').trim();
  return {
    resource_id: rec.id || null,
    nombre: nombre || rec.name || null,
    nombre_corto: emp.first_name || rec.name || null,
  };
}).filter((p) => p.resource_id);

const quienes = personas.map((p) => p.nombre_corto).filter(Boolean);

if (!consulta) {
  // Sin nombre no hay nada que resolver: el pool completo, como hasta ahora.
  return [{ json: { ok: true, resource_id: null, nombre: null, quienes } }];
}

const q = plano(consulta);
const casa = (p) => {
  const completo = plano(p.nombre);
  const corto = plano(p.nombre_corto);
  return completo === q || corto === q || completo.split(' ').includes(q) || completo.includes(q);
};

const candidatos = personas.filter(casa);

if (candidatos.length === 1) {
  return [{ json: { ok: true, resource_id: candidatos[0].resource_id,
                    nombre: candidatos[0].nombre_corto, quienes } }];
}
if (candidatos.length > 1) {
  return [{ json: { ok: false, motivo: 'varios_profesionales',
                    opciones: candidatos.map((p) => p.nombre), quienes } }];
}

// No está en el pool. ¿Existe siquiera? Distinguir importa: "Arturo no lleva
// altas de autónomo" y "no tengo a ningún Arturo" son dos conversaciones muy
// distintas, y dar la segunda cuando toca la primera queda fatal.
const enPlantilla = plantilla.filter((e) => {
  const completo = plano([e.first_name, e.last_name].filter(Boolean).join(' '));
  return completo === q || completo.split(' ').includes(q) || completo.includes(q);
});

if (enPlantilla.length > 0) {
  return [{ json: { ok: false, motivo: 'profesional_no_presta_servicio',
                    nombre: enPlantilla[0].first_name || consulta, quienes } }];
}
return [{ json: { ok: false, motivo: 'profesional_desconocido',
                  nombre: consulta, quienes } }];
